contract_clause_fact(contrato_ocs_231_2020, clausula_decima_primeira_obrigações_contratada, obrigacoes, 'reparar todos os danos diretos causados ao BNDES ou a terceiros', 'trecho_literal').
contract_clause_fact(contrato_ocs_231_2020, clausula_decima_primeira_obrigações_contratada, obrigacoes, 'pagar todos os encargos e tributos, que incidam ou venham a incidir, direta ou indiretamente, sobre o objeto deste Contrato', 'trecho_literal').
contract_clause_fact(contrato_ocs_231_2020, clausula_decima_primeira_obrigações_contratada, obrigacoes, 'providenciar, perante a Receita Federal do Brasil – RFB, comprovando ao BNDES, sua exclusão obrigatória do  Simples Nacional, no prazo estipulado pelo artigo 30 da Lei Complementar nº 123/2006', 'trecho_literal').
contract_clause_fact(contrato_ocs_231_2020, clausula_decima_primeira_obrigações_contratada, obrigacoes, 'permitir vistorias e acompanhamento da execução do objeto pelo Gestor do Contrato', 'trecho_literal').
