contract_clause_fact(contrato_ocs_231_2020, clausula_decima_primeira_obrigações_contratada, obrigacoes, 'garantir que o objeto do Contrato não infringe quaisquer direitos autorais, patentes ou registros, inclusive marcas, know-how ou trade-secrets', 'trecho_literal').
